/* From Uiverse.io by PriyanshuGupta28 - Tags: checkbox, docs checkbox, cool checkbox */
.__UIV_SCOPE__ .checkbox-wrapper input[type="checkbox"] {
  visibility: hidden;
  display: none;
}

.__UIV_SCOPE__ .checkbox-wrapper *,
  .__UIV_SCOPE__ .checkbox-wrapper ::after,
  .__UIV_SCOPE__ .checkbox-wrapper ::before {
  box-sizing: border-box;
  user-select: none;
}

.__UIV_SCOPE__ .checkbox-wrapper {
  position: relative;
  display: block;
  overflow: hidden;
}

.__UIV_SCOPE__ .checkbox-wrapper .label {
  cursor: pointer;
}

.__UIV_SCOPE__ .checkbox-wrapper .check {
  width: 50px;
  height: 50px;
  position: absolute;
  opacity: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper .label svg {
  vertical-align: middle;
}

.__UIV_SCOPE__ .checkbox-wrapper .path1 {
  stroke-dasharray: 400;
  stroke-dashoffset: 400;
  transition: .5s stroke-dashoffset;
  opacity: 0;
}

.__UIV_SCOPE__ .checkbox-wrapper .check:checked + label svg g path {
  stroke-dashoffset: 0;
  opacity: 1;
}
